def dynamic_fields(doc, prefix=""):
    out = []
    for k, v in doc.items():
        name = prefix + k
        if isinstance(v, dict):
            out += dynamic_fields(v, name + ".")
        elif isinstance(v, str):
            out += [name, name + ".keyword"]   # text + keyword 두 벌
        else:
            out.append(name)
    return out

logs = [
    {"service": "order", "level": "INFO", "request": {"userId": "u1", "symbol": "AAPL", "qty": 3}},
    {"service": "quote", "level": "WARN", "request": {"symbols": "TSLA,NVDA", "depth": 10}},
    {"service": "order", "level": "INFO", "response": {"orderId": "o9", "status": "FILLED", "fee": 0.12}},
]
fields = set()
for d in logs:
    fields |= set(dynamic_fields(d))
print("동적 매핑 필드 수:", len(fields))                      # 17
print("명시 매핑 + flattened:", len({"service", "level", "request", "response"}))  # 4
